    18	export default meta;
    19	type Story = StoryObj<typeof Footer>;
    20	
    21	export const Default: Story = {
    22	  render: (args) => (
    23	    <div style={{ width: '100%' }}>
    24	      <Footer {...args} />
    25	    </div>
    26	  ),
    27	  // Asserts leavesTheSite's scheme branch. Security-adjacent: rel="noopener noreferrer" is what
    28	  // stops the storefront URL reaching WhatsApp in the Referer header, and the accessible-name
    29	  // suffix is WCAG 3.2.5. Nothing else in CI covered this — the behaviour was only ever verified
    30	  // by hand, which is exactly the kind of gap that survives a refactor invisibly.
    31	  play: async ({ canvasElement }) => {
    32	    const canvas = within(canvasElement);
    33	
    34	    // http(s) → new tab, hardened, and the name says so
    35	    const whatsApp = canvas.getByRole('link', { name: /whatsapp/i });
    36	    await expect(whatsApp).toHaveAttribute('target', '_blank');
    37	    await expect(whatsApp).toHaveAttribute('rel', 'noopener noreferrer');
    38	    await expect(whatsApp).toHaveAccessibleName(/opens in a new tab/i);
    39	
    40	    // tel:/mailto: hand off to the OS — a target would do nothing, so there must not be one
    41	    for (const name of [/call us/i, /email us/i]) {
    42	      const link = canvas.getByRole('link', { name });
    43	      await expect(link).not.toHaveAttribute('target');
    44	      await expect(link).not.toHaveAccessibleName(/opens in a new tab/i);
    45	    }
    46	  },
    47	};
    48	
    49	export const Subscribed: Story = {
    50	  args: {
    51	    initialSubscribed: true,
    52	  },
    53	  render: (args) => (
    54	    <div style={{ width: '100%' }}>
    55	      <Footer {...args} />
    56	    </div>
    57	  ),
    58	};
    59	
    60	export const SubscribeSubmit: Story = {
    61	  name: 'Subscribe — two-step flow (HPC-035, not shipped)',
    62	  // enableNameCapture is opt-in and off in production: SFCC-55 ships the placeholder path
    63	  // below. This story keeps the modal exercised so HPC-035 inherits working, covered code.
    64	  render: (args) => (
    65	    <div style={{ width: '100%' }}>
    66	      <Footer {...args} privacyPolicyHref="/privacy-policy" enableNameCapture />
    67	    </div>
    68	  ),
    69	  play: async ({ canvasElement }) => {
    70	    // Step 1 — email entry
    71	    const canvas = within(canvasElement);
    72	    const emailInput = canvas.getByRole('textbox', { name: /email/i });
    73	    await userEvent.type(emailInput, 'test@example.com');
    74	    const submitBtn = canvas.getByRole('button', { name: /subscribe/i });
    75	    await userEvent.click(submitBtn);
    76	
    77	    // Step 2 — modal should open. testing.md §Layer-2 requires within(canvasElement);
    78	    // portal exception: createPortal attaches the dialog to document.body, outside the
    79	    // Storybook canvas boundary, so within(document.body) is the required workaround.
    80	    const doc = within(document.body);
    81	    await expect(doc.getByRole('dialog')).toBeInTheDocument();
    82	    await userEvent.type(doc.getByRole('textbox', { name: /first name/i }), 'Jane');
    83	    await userEvent.type(doc.getByRole('textbox', { name: /last name/i }), 'Smith');
    84	    await userEvent.click(doc.getByRole('button', { name: /continue/i }));
    85	
    86	    // Modal closes. HPC-036 not yet landed → component shows the 'unavailable' message
    87	    // rather than false success. Update this assertion to /on the list/i once the Omneo
    88	    // POST is wired and setSubmitState('success') is reachable via a real API response.
    89	    await expect(doc.queryByRole('dialog')).not.toBeInTheDocument();
    90	    await expect(canvas.getByText(/temporarily unavailable/i)).toBeInTheDocument();
    91	  },
    92	};
    93	
    94	export const SubscribeModalOpen: Story = {
    95	  name: 'Subscribe — modal open state (HPC-035, not shipped)',
    96	  render: (args) => (
    97	    <div style={{ width: '100%' }}>
    98	      <Footer {...args} privacyPolicyHref="/privacy-policy" enableNameCapture />
    99	    </div>
   100	  ),
   101	  // Covers the dialog mechanics now owned by useZimmModal: focus entry, the Tab trap in
   102	  // both wrap directions, the body-scroll lock, Escape dismissal and focus restore. Mutation-
   103	  // tested — breaking the setTimeout focus, the Escape branch, the Tab branch or the overflow
   104	  // write each fails this play. Before it existed, those mutations passed the whole Storybook
   105	  // suite, so the hook extraction would have had no CI net at all.
   106	  //
   107	  // The one branch this cannot reach is the trap's `!el.hasAttribute('disabled')` filter:
   108	  // nothing in SubscribeModal is ever disabled, so there is no disabled control here for it to
   109	  // exclude. That one is covered with a synthetic harness in hooks/useZimmModal.test.tsx.
   110	  play: async ({ canvasElement }) => {
   111	    const canvas = within(canvasElement);
   112	
   113	    // Read, not assumed: the hook restores whatever inline value it found, so the release
   114	    // assertion at the end compares against this rather than a hardcoded ''. Asserting it is
   115	    // not ALREADY 'hidden' is what stops the lock assertion below from passing vacuously.
   116	    const overflowBefore = document.body.style.overflow;
   117	    await expect(overflowBefore).not.toBe('hidden');
   118	
   119	    await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
   120	    const trigger = canvas.getByRole('button', { name: /subscribe/i });
   121	    await userEvent.click(trigger);
   122	
   123	    // Portal renders outside canvasElement — testing.md §Layer-2 exception.
   124	    const doc = within(document.body);
   125	    const dialog = doc.getByRole('dialog');
   126	    await expect(dialog).toBeInTheDocument();
   127	    await expect(dialog).toHaveAttribute('aria-modal', 'true');
   128	
   129	    // Scroll lock: the page behind a modal must not scroll out from under it.
   130	    await expect(document.body.style.overflow).toBe('hidden');
   131	
   132	    // Focus is moved into the dialog, onto the first field
   133	    const firstName = doc.getByRole('textbox', { name: /first name/i });
   134	    await expect(firstName).toHaveFocus();
   135	
   136	    // Tab trap, both wrap directions (WCAG 2.1.2 — no keyboard trap that cannot be escaped,
   137	    // and no tabbing out of a modal dialog). The form's focus order is firstName, lastName,
   138	    // Privacy Policy, Cancel, Continue, so firstName is `first` and Continue is `last`.
   139	    //
   140	    // Continue is focused programmatically rather than clicked: it is the submit button, so a
   141	    // click would close the dialog before the trap could be exercised. The wrap assertions are
   142	    // sound despite userEvent moving focus itself — the hook's document-level keydown listener
   143	    // calls preventDefault on a wrap, and userEvent skips its own focus move when the keydown
   144	    // is defaultPrevented, so the focus observed below is the trap's and nothing else's.
   145	    const continueButton = doc.getByRole('button', { name: /continue/i });
   146	    continueButton.focus();
   147	    await expect(continueButton).toHaveFocus();
   148	
   149	    await userEvent.tab();
   150	    await expect(firstName).toHaveFocus();
   151	
   152	    await userEvent.tab({ shift: true });
   153	    await expect(continueButton).toHaveFocus();
   154	
   155	    // Escape dismisses it and focus returns to the control that opened it (WCAG 2.4.3)
   156	    await userEvent.keyboard('{Escape}');
   157	    await expect(doc.queryByRole('dialog')).not.toBeInTheDocument();
   158	    await expect(trigger).toHaveFocus();
   159	
   160	    // ...and the lock is released to whatever was there before, not blindly to ''.
   161	    await expect(document.body.style.overflow).toBe(overflowBefore);
   162	  },
   163	};
