   190	    const canvas = within(canvasElement);
   191	
   192	    // Absent and unsafe both render the icon as a labelled span: no href, no tab stop, so
   193	    // nothing promises an action that cannot be performed (WCAG 2.4.4 / 3.2.4) — but the
   194	    // channel stays perceivable rather than silently disappearing.
   195	    for (const name of [/call us/i, /whatsapp/i]) {
   196	      await expect(canvas.queryByRole('link', { name })).not.toBeInTheDocument();
   197	      await expect(canvas.getByRole('img', { name })).toBeInTheDocument();
   198	    }
   199	
   200	    // The safe channel is unaffected — degradation is per-channel, not all-or-nothing.
   201	    await expect(canvas.getByRole('link', { name: /email us/i })).toHaveAttribute('href', 'mailto:care@zimmermann.com');
   202	  },
   203	};
   204	
   205	/**
   206	 * The path SFCC-55 actually ships. Its AC scopes the Stay in Touch section to "an email input
   207	 * field and submit button as a placeholder component" and defers the Omneo sign-up, so a valid
   208	 * email resolves straight to the placeholder message with no name-capture modal.
   209	 */
   210	export const SubscribePlaceholder: Story = {
   211	  name: 'Subscribe — placeholder path (SFCC-55 default)',
   212	  render: (args) => (
   213	    <div style={{ width: '100%' }}>
   214	      <Footer {...args} />
   215	    </div>
   216	  ),
   217	  play: async ({ canvasElement }) => {
   218	    const canvas = within(canvasElement);
   219	    // Guarded rather than cast: the only work an `as HTMLElement` did here was suppress the
   220	    // `possibly null` errors, and it narrowed away nothing useful — getBoundingClientRect is
   221	    // declared on Element. A missing node throws either way, so this only decides whether the
   222	    // failure names the selector that went missing or reads as a bare "of null".
   223	    const footer = canvasElement.querySelector('footer[role="contentinfo"]');
   224	    if (!footer) throw new Error('SubscribePlaceholder: footer[role="contentinfo"] not found');
   225	    const slot = footer.querySelector('[aria-live]');
   226	    if (!slot) throw new Error('SubscribePlaceholder: subscribe [aria-live] slot not found');
   227	
   228	    const heightBefore = footer.getBoundingClientRect().height;
   229	    const slotBefore = slot.getBoundingClientRect().height;
   230	
   231	    // S2 preconditions. The two equality checks below are pure before/after comparisons, so a
   232	    // collapsed container satisfies them vacuously: display:none, height:0;overflow:hidden and
   233	    // an ancestor display:none each measure 0 both times and pass. Every rect is 0 in jsdom too,
   234	    // which would make the whole assertion unconditionally true if this play is ever driven
   235	    // through portable stories. Anchoring both operands above zero is what makes it an assertion.
   236	    await expect(slotBefore).toBeGreaterThan(0);
   237	    await expect(heightBefore).toBeGreaterThan(0);
   238	
   239	    await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
   240	    await userEvent.click(canvas.getByRole('button', { name: /subscribe/i }));
   241	
   242	    // No modal — the default build does not collect names (HPC-035 is a separate story with no
   243	    // design yet). Queried against document.body because the modal would portal outside canvas.
   244	    await expect(within(document.body).queryByRole('dialog')).not.toBeInTheDocument();
   245	
   246	    // The shopper still gets honest feedback rather than a false success.
   247	    await expect(canvas.getByText(/temporarily unavailable/i)).toBeInTheDocument();
   248	    await expect(canvas.queryByText(/on the list/i)).not.toBeInTheDocument();
   249	
   250	    // No layout shift. The field and the message are different heights (45px vs 36px of text),
   251	    // so without subscribeControl's minHeight reservation the column re-flows — measurably at
   252	    // every viewport, and visibly on mobile where the columns stack and the footer itself moves.
   253	    // Asserted on the slot as well as the footer: at desktop widths the taller site-map column
   254	    // sets the row height, so a footer-only check passes even when the column has shifted.
   255	    // One decimal place. getBoundingClientRect reports sub-pixel jitter, so comparing raw
   256	    // values would fail an equality check on a layout that did not actually move.
   257	    const LAYOUT_PRECISION_DP = 1;
   258	    const rounded = (n: number) => Number(n.toFixed(LAYOUT_PRECISION_DP));
   259	    await expect(rounded(slot.getBoundingClientRect().height)).toBe(rounded(slotBefore));
   260	    await expect(rounded(footer.getBoundingClientRect().height)).toBe(rounded(heightBefore));
   261	  },
   262	};
