    14	export const Default: Story = {
    15	  args: {
    16	    phoneHref: 'tel:+61280000000',
    17	    whatsAppHref: 'https://wa.me/61280000000',
    18	    emailHref: 'mailto:care@zimmermann.com',
    19	  },
    20	  // Asserts leavesTheSite's scheme branch. Security-adjacent: rel="noopener noreferrer" is what
    21	  // stops the storefront URL reaching WhatsApp in the Referer header, and the accessible-name
    22	  // suffix is WCAG 3.2.5.
    23	  play: async ({ canvasElement }) => {
    24	    const canvas = within(canvasElement);
    25	
    26	    const whatsApp = canvas.getByRole('link', { name: /whatsapp/i });
    27	    await expect(whatsApp).toHaveAttribute('target', '_blank');
    28	    await expect(whatsApp).toHaveAttribute('rel', 'noopener noreferrer');
    29	    await expect(whatsApp).toHaveAccessibleName(/opens in a new tab/i);
    30	
    31	    for (const name of [/call us/i, /email us/i]) {
    32	      const link = canvas.getByRole('link', { name });
    33	      await expect(link).not.toHaveAttribute('target');
    34	      await expect(link).not.toHaveAccessibleName(/opens in a new tab/i);
    35	    }
    36	  },
    37	};
    38	
    39	/**
    40	 * Absent and unsafe hrefs both fall through to a labelled, non-interactive span — see the
    41	 * isSafeHref guard in index.tsx. Footer-level coverage of this same branch, in context, lives in
    42	 * footer/index.stories.tsx's ContactChannelFallbacks; this is the isolated version.
    43	 */
    44	export const NoUsableDestination: Story = {
    45	  name: 'Absent and unsafe hrefs',
    46	  args: {
    47	    phoneHref: undefined,
    48	    whatsAppHref: 'javascript:alert(1)',
    49	    emailHref: 'mailto:care@zimmermann.com',
    50	  },
    51	  play: async ({ canvasElement }) => {
    52	    const canvas = within(canvasElement);
    53	    for (const name of [/call us/i, /whatsapp/i]) {
    54	      await expect(canvas.queryByRole('link', { name })).not.toBeInTheDocument();
    55	      await expect(canvas.getByRole('img', { name })).toBeInTheDocument();
    56	    }
    57	    await expect(canvas.getByRole('link', { name: /email us/i })).toHaveAttribute('href', 'mailto:care@zimmermann.com');
    58	  },
    59	};

