    36	export const Default: Story = {
    37	  render: () => <OpenSubscribeModalExample />,
    38	  play: async () => {
    39	    // `find*`, not `get*`: useZimmModal starts `mounted: false` and ZimmModal returns null until
    40	    // it flips in an effect, so the portal contents do not exist on the first synchronous pass.
    41	    // `getByRole` threw before the effect had run. Queried through document.body rather than
    42	    // canvasElement because ZimmModal renders via createPortal — testing.md's canvasElement rule
    43	    // can't reach a portal root, which is why the scope was already widened here.
    44	    const doc = within(document.body);
    45	    await expect(await doc.findByRole('dialog')).toBeInTheDocument();
    46	    await expect(await doc.findByRole('heading', { name: /join us/i })).toBeInTheDocument();
    47	    await expect(await doc.findByRole('link', { name: /privacy policy/i })).toBeInTheDocument();
    48	  },
    49	};
